// Behaviour model of the counted def pointer assignment.
struct Def { long RefCount; int destroyed; };
struct Ptr {
    Def* Object;
    Ptr& assign(const Ptr& o)
    {
        if (Object != o.Object) {
            if (Object) { if (--Object->RefCount == 0) ++Object->destroyed; Object = 0; }
            Object = o.Object;
            if (Object) ++Object->RefCount;
        }
        return *this;
    }
};
