    E* ns = len ? (E*)std::malloc(len * sizeof(E)) : 0;
    E* nf = ns;
    for (E* p = vec.s; p != pos; ++p, ++nf) new (nf) E(*p);
    if (fill_len == 1) { new (nf) E(x); ++nf; }
    else for (unsigned int n = fill_len; n > 0; --n, ++nf) new (nf) E(x);
    if (!atend) for (E* p = pos; p != vec.f; ++p, ++nf) new (nf) E(*p);
