{
    ++g_dispatch;
    for (; first != last; first = first->next) {
        Node* n = (Node*)std::malloc(sizeof(Node)); *n = *first;
        n->next = head; n->prev = head->prev; head->prev->next = n; head->prev = n;
    }
}
static Rec* uninit_copy(const Rec* first, const Rec* last, Rec* result)
{
