    for (; first != last; ++first, ++cur) {
        cur->keylo = first->keylo; cur->keyhi = first->keyhi;
        Node* h = (Node*)std::malloc(sizeof(Node)); h->next = h; h->prev = h; cur->head = h;
        insert_range(h, first->head->next, first->head);
    }
    return cur;
